import{prediction}from'./core.mjs';
const n=x=>Number(x).toFixed(3);
export function clipImageLine(l,w,h){const[a,b,c]=l,pts=[];for(const[x,y]of[[0,-c/b],[w,-(c+a*w)/b],[-c/a,0],[-(c+b*h)/a,h]])if(Number.isFinite(x)&&Number.isFinite(y)&&x>=-1e-8&&x<=w+1e-8&&y>=-1e-8&&y<=h+1e-8&&!pts.some(p=>Math.hypot(p[0]-x,p[1]-y)<1e-7))pts.push([x,y]);return pts.length>=2?[pts[0],pts[1]]:null;}
export function diagram(f,result,state){const w=f.width,h=f.height,inside=p=>p[0]>=0&&p[0]<=w&&p[1]>=0&&p[1]<=h,line=(a,b,color,extra='')=>`<line x1="${n(a[0])}" y1="${n(a[1])}" x2="${n(b[0])}" y2="${n(b[1])}" stroke="${color}" ${extra}/>`;let shapes='';const weak=result?.fit.warnings.includes('nonunique_or_ill_conditioned_source');f.pairs.forEach((p,i)=>{const held=!f.training.includes(i),color=held?'#efd093':'#8fcfc3',selected=i===state.selected;if(state.lines&&result&&!weak){const predicted=prediction(p,result.fit.source_image_homogeneous),ends=predicted&&clipImageLine(predicted.line,w,h);if(ends)shapes+=line(...ends,color,`opacity="${selected?1:.23}" stroke-width="${selected?3:1}" ${held?'stroke-dasharray="8 6"':''}`);if(selected&&predicted)shapes+=line(p.receiver,predicted.perpendicularFoot,'#ff9990','stroke-width="4"');}shapes+=line(p.aperture,p.receiver,color,`opacity=".6" stroke-width="${selected?3:1}"`);if(inside(p.aperture))shapes+=`<circle cx="${n(p.aperture[0])}" cy="${n(p.aperture[1])}" r="${selected?9:6}" fill="#14281e" stroke="${color}" stroke-width="3"/><text x="${n(p.aperture[0]+11)}" y="${n(p.aperture[1]-11)}" fill="${color}" font-size="19">${i+1}</text>`;if(inside(p.receiver))shapes+=`<rect x="${n(p.receiver[0]-5)}" y="${n(p.receiver[1]-5)}" width="10" height="10" fill="${color}"/>`;});if(result&&!result.fit.source_image_finite&&!weak){const v=result.fit.source_image_homogeneous,scale=80/Math.hypot(v[0],v[1]),a=[w/2,h/2],b=[a[0]+v[0]*scale,a[1]+v[1]*scale];shapes+=line(a,b,'#dba7eb','stroke-width="5"')+`<text x="${n(a[0])}" y="${n(a[1]-20)}" fill="#dba7eb" font-size="18">image direction only · infinity</text>`;}const src=result?.fit.source_image_finite;if(src&&inside(src)&&!weak)shapes+=`<circle cx="${n(src[0])}" cy="${n(src[1])}" r="12" fill="#dba7eb"/><text x="${n(src[0]+16)}" y="${n(src[1])}" fill="#dba7eb" font-size="20">image intersection</text>`;return`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Synthetic image coordinates. Circles are apertures, squares receiver picks. Mint training rays and dashed gold held-out predictions." style="width:100%;height:auto;display:block;background:#14281e;border:1px solid #4d6556"><defs><clipPath id="projection-clip"><rect width="${w}" height="${h}"/></clipPath></defs><g clip-path="url(#projection-clip)">${shapes}</g></svg>`;}
